try:
    print('>>> f = map')
    print('>>> x = bytearray()')
    print('>>> y = (1, 2)')
    print('>>> f(x, y)')
    f = map
    x = bytearray()
    y = (1, 2)
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
